 const exportCsv=()=>{const rows=[['رقم الطلب','العميل','الموبايل','المنطقة','الخدمة','الحالة','المبلغ','رسوم التوصيل','التاريخ'],...visible.map(o=>[o.id,o.customer_name,o.customer_phone,o.area,services.find(s=>s.id===o.service_id)?.name||'',statusLabel[o.status],o.collection_amount,o.delivery_fee,new Date(o.created_at).toLocaleString('ar-EG')])];const csv='\uFEFF'+rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='mersal-orders.csv';a.click();URL.revokeObjectURL(a.href)};
 const exportPdf=()=>{const esc=(v:any)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));const w=window.open('','_blank');if(!w){flash('اسمح بفتح نافذة التقرير لطباعة PDF');return}const rows=visible.map(o=>`<tr><td>${esc(o.customer_name)}</td><td>${esc(o.customer_phone)}</td><td>${esc(serviceLabel(o))}</td><td>${esc(o.area)}</td><td>${esc(statusLabel[o.status])}</td><td>${esc(o.collection_amount)} ج.م</td></tr>`).join('');w.document.write(`<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>تقرير طلبات مرسال</title><style>body{font-family:Tahoma,Arial;padding:28px;color:#222}h1{color:#b87500}table{border-collapse:collapse;width:100%;margin-top:24px}th,td{border:1px solid #ddd;padding:9px;text-align:right}th{background:#fff2d4}@media print{button{display:none}}</style><h1>مرسال للخدمات المتكاملة</h1><p>تقرير الطلبات · ${new Date().toLocaleDateString('ar-EG')}</p><button onclick="print()">طباعة / حفظ PDF</button><table><thead><tr><th>العميل</th><th>الهاتف</th><th>الخدمة</th><th>المنطقة</th><th>الحالة</th><th>المبلغ</th></tr></thead><tbody>${rows}</tbody></table><script>window.onload=()=>setTimeout(()=>window.print(),300)</script></html>`);w.document.close()};
 const loadReport=async(from=reportFrom,to=reportTo)=>{if(!from||!to){flash('اختار تاريخ البداية والنهاية');return}if(from>to){flash('تاريخ البداية لازم يكون قبل تاريخ النهاية');return}setReportLoading(true);try{const start=cairoMidnightUtc(from).toISOString(),end=cairoMidnightUtc(nextDateKey(to)).toISOString(),grab=async(kind:'created'|'delivered')=>{const out:Order[]=[];for(let page=0;page<20;page++){const base=kind==='created'?supabase.from('orders').select('*').gte('created_at',start).lt('created_at',end).order('created_at',{ascending:false}):supabase.from('orders').select('*').eq('status','delivered').gte('delivered_at',start).lt('delivered_at',end).order('delivered_at',{ascending:false});const {data,error}=await base.range(page*1000,page*1000+999);if(error)throw error;out.push(...((data||[]) as Order[]));if((data||[]).length<1000)break}return out};const [created,delivered,settlements]=await Promise.all([grab('created'),grab('delivered'),supabase.from('courier_settlements').select('*').gte('settled_at',start).lt('settled_at',end).order('settled_at',{ascending:false})]);if(settlements.error)throw settlements.error;const map=new Map<string,Order>();for(const o of [...created,...delivered])map.set(o.id,o);setReportOrders([...map.values()]);setReportSettlementHistory((settlements.data||[]) as CourierSettlement[]);setAppliedReportRange({from,to});setReportLoaded(true)}catch(e:any){flash(e?.message||'تعذر تحميل التقرير')}finally{setReportLoading(false)}};
 const exportReportCsv=()=>{const rows=[['تقرير مرسال','من',appliedReportRange.from,'إلى',appliedReportRange.to],[],['رقم الطلب','العميل','الموبايل','المنطقة','الخدمة','الحالة','المبلغ','رسوم التوصيل','تاريخ الإنشاء','تاريخ التسليم'],...reportRows.map(o=>[o.id,o.customer_name,o.customer_phone,`${o.area}، ${o.governorate}`,services.find(s=>s.id===o.service_id)?.name||'',statusLabel[o.status],o.collection_amount,o.delivery_fee,new Date(o.created_at).toLocaleString('ar-EG'),o.delivered_at?new Date(o.delivered_at).toLocaleString('ar-EG'):'']),['الإجمالي','','','','','',reportCollections,reportFees,'','']];const csv='\uFEFF'+rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`mersal-report-${appliedReportRange.from}_${appliedReportRange.to}.csv`;a.click();URL.revokeObjectURL(a.href)};
 const exportReportPdf=()=>{const esc=(v:any)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));const w=window.open('','_blank');if(!w){flash('اسمح بفتح نافذة التقرير لطباعة PDF');return}const rows=reportRows.map(o=>`<tr><td>${esc(o.customer_name)}</td><td>${esc(o.customer_phone)}</td><td>${esc(serviceLabel(o))}</td><td>${esc(o.area)}</td><td>${esc(statusLabel[o.status])}</td><td>${esc(o.collection_amount)} ج.م</td><td>${esc(o.delivery_fee)} ج.م</td><td>${o.delivered_at?esc(new Date(o.delivered_at).toLocaleDateString('ar-EG')):'-'}</td></tr>`).join('');w.document.write(`<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>تقرير مرسال</title><style>body{font-family:Tahoma,Arial;padding:28px;color:#222}h1{color:#b87500}table{border-collapse:collapse;width:100%;margin-top:24px}th,td{border:1px solid #ddd;padding:9px;text-align:right}th{background:#fff2d4}@media print{button{display:none}}</style><h1>مرسال للخدمات المتكاملة</h1><p>تقرير الفترة: ${esc(rangeLabel)}</p><p>إجمالي الطلبات: ${reportCreatedOrders.length} · تم تسليمها: ${reportDeliveredOrders.length} · ملغية: ${reportCancelled}</p><p>رسوم التوصيل: ${esc(money(reportFees))} · تحصيلات الطلبات: ${esc(money(reportCollections))} · حصة المكتب: ${esc(money(settlementTotals.office))}</p><button onclick="print()">طباعة / حفظ PDF</button><table><thead><tr><th>العميل</th><th>الهاتف</th><th>الخدمة</th><th>المنطقة</th><th>الحالة</th><th>المبلغ</th><th>رسوم التوصيل</th><th>تاريخ التسليم</th></tr></thead><tbody>${rows}</tbody></table><script>window.onload=()=>setTimeout(()=>window.print(),300)</script></html>`);w.document.close()};

